arguments.script:
var rig=UnityEngine.Object.FindObjectOfType<Character.Control.PaddleCharacterVisual>();rig.Pose();
var root=new UnityEngine.GameObject("Collision outline preview");root.hideFlags=UnityEngine.HideFlags.DontSave;
void Line(string name,UnityEngine.Vector3[] pts,UnityEngine.Color color){var g=new UnityEngine.GameObject(name);g.transform.SetParent(root.transform);var lr=g.AddComponent<UnityEngine.LineRenderer>();lr.sharedMaterial=new UnityEngine.Material(UnityEngine.Shader.Find("Sprites/Default"));lr.startColor=lr.endColor=color;lr.startWidth=lr.endWidth=.012f;lr.positionCount=pts.Length;lr.SetPositions(pts);lr.loop=true;lr.sortingOrder=2000;lr.sortingLayerID=rig.torso.sortingLayerID;}
foreach(var c in rig.GetComponentsInChildren<UnityEngine.PolygonCollider2D>())if(c.enabled){var v=c.GetPath(0);Line(c.name,v.Select(x=>c.transform.TransformPoint(x+c.offset)).ToArray(),UnityEngine.Color.green);}
var tr=rig.tip.GetComponent<UnityEngine.CapsuleCollider2D>();float radius=tr.size.y*.5f;float straight=UnityEngine.Mathf.Max(0,tr.size.x*.5f-radius);var points=new System.Collections.Generic.List<UnityEngine.Vector3>();for(int i=0;i<32;i++){float a=i*UnityEngine.Mathf.PI*2/32;var v=tr.offset+new UnityEngine.Vector2(UnityEngine.Mathf.Cos(a)*radius+(UnityEngine.Mathf.Cos(a)>=0?straight:-straight),UnityEngine.Mathf.Sin(a)*radius);points.Add(tr.transform.TransformPoint(v));}Line("Blade trigger",points.ToArray(),UnityEngine.Color.magenta);
var view=UnityEditor.SceneView.lastActiveSceneView;view.in2DMode=true;view.LookAt(rig.body.position+UnityEngine.Vector3.up*.3f,UnityEngine.Quaternion.identity,2.4f,true,true);view.Repaint();
UnityEngine.Debug.Log("Physical polygons green; blade detection capsule magenta. Old handle box enabled="+rig.tool.Find("Shape/HandleExtension").GetComponent<UnityEngine.BoxCollider2D>().enabled);
